import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.InetAddress;
import java.net.URL;
import java.net.UnknownHostException;

public class SecureApp {
    public static void main(String[] args) throws IOException {
        String urlString = "http://example.com";
        if (args.length > 0) {
            urlString = args[0];
        }

        URL url = new URL(urlString);

        // Validate the host to prevent SSRF by resolving IP and checking for private addresses
        String host = url.getHost();
        InetAddress address = InetAddress.getByName(host);

        if (address.isLoopbackAddress() || address.isAnyLocalAddress() || address.isMulticastAddress()) {
             throw new SecurityException("Access denied: localhost or multicast addresses are not allowed.");
        }

        // Check against common private IP ranges manually or use a library like BouncyCastle/OWASP validator
        if (isPrivateIp(address)) {
            throw new SecurityException("Access denied: private IP addresses are not allowed.");
        }

        try (BufferedReader in = new BufferedReader(new InputStreamReader(url.openStream()))) {
            System.out.println(in.readLine());
        }
    }

    // Helper method to check for private, link-local, loopback, etc.
    private static boolean isPrivateIp(java.net.InetAddress address) {
        return address.isLooploopAddress() || address.isAnyLocalAddress() || 
               address.isMulticastAddress() || address.isLinkLocalAddress() || 
               address.isSiteLocalAddress();
    }
}
